import java.io.*;
import java.net.http.*;
import java.net.URI;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.WebServlet;
import org.apache.commons.text.StringSubstitutor;
import org.apache.commons.text.lookup.StringLookupFactory;
import java.util.HashMap;
import java.util.Map;
import java.sql.*;

@WebServlet("/render")
public class NotificationServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String userId = req.getParameter("user_id");
        String messageTemplate = req.getParameter("message");

        if (userId == null || messageTemplate == null) {
            resp.sendError(400, "Missing parameters");
            return;
        }

        // Fetch user details for template substitution
        Map<String, String> userData = new HashMap<>();
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            PreparedStatement ps = conn.prepareStatement(
                "SELECT display_name, email, plan_tier FROM users WHERE id = ?");
            ps.setString(1, userId);
            ResultSet rs = ps.executeQuery();
            if (rs.next()) {
                userData.put("name", rs.getString("display_name"));
                userData.put("email", rs.getString("email"));
                userData.put("tier", rs.getString("plan_tier"));
            }
        } catch (SQLException e) {
            resp.sendError(500, "Database error");
            return;
        }

        // Render the notification message using Apache Commons Text interpolation
        // This supports ${prefix:name} syntax for variable substitution
        StringSubstitutor sub = new StringSubstitutor(
            StringLookupFactory.INSTANCE.interpolatorStringLookup(
                userData, null, true
            )
        );
        sub.setEnableSubstitutionInVariables(true);
        sub.setEnableUndefinedVariableException(false);

        String rendered = sub.replace(messageTemplate);

        // Log the rendered message
        System.out.println("Rendered notification for user " + userId + ": " + rendered);

        // Send response
        resp.setContentType("text/plain");
        resp.getWriter().write(rendered);
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        resp.setContentType("text/html");
        resp.getWriter().write("<form method=POST action='/render'>" +
            "<input name='user_id' placeholder='User ID'>" +
            "<textarea name='message' placeholder='Hello ${name}!'></textarea>" +
            "<button>Preview</button></form>");
    }
}
